package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.List;

/** A holder's share of a claim: the person holding it and their percent, two decimals. */
public record ClaimShare(long personId, BigDecimal share) {

    /** Their part of a due figure: the figure times their share divided by 100, rounded half to even. */
    public BigDecimal partOf(BigDecimal figure) {
        return figure.multiply(share).movePointLeft(2).setScale(2, RoundingMode.HALF_EVEN);
    }

    /** Shares added up: 0.00 when there are none. */
    public static BigDecimal total(List<ClaimShare> shares) {
        return shares.stream().map(ClaimShare::share).reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheet;

/**
 * The number a claim takes when it is settled (or approved): the next within the fiscal year of its due-by, in the
 * sequence the sheet's tree shares (<FY>-<n>), or, while the sheet's period
 * numbering from is set and its today is on or after it, the next within the claim's period (the one containing its due-by)
 * (<period name>-<n>), or X-<n> when the claim is in no period.
 */
public final class ClaimNumbers {
    private ClaimNumbers() {}

    /**
     * Gives a claim just SETTLED that has no number yet the next number in its sequence, by the
     * due-by that places it now; a claim already numbered keeps its number.
     */
    public static void giveOnSettle(Sheet sheet, Claim claim, Settings settings, PeriodRepository periods,
            ClaimRepository claims) {
        if (claim.getStatus() != ClaimStatus.SETTLED || claim.getNumber() != null) return;
        claim.setNumber(next(sheet, claim, settings, periods, claims));
    }

    public static String next(Sheet sheet, Claim claim, Settings settings, PeriodRepository periods, ClaimRepository claims) {
        if (!settings.numbersByPeriod(sheet.today())) {
            String fiscalYear = settings.fiscalYearOf(claim.getDueBy());
            return fiscalYear + "-" + claims.nextNumberInFiscalYear(sheet.id(), fiscalYear);
        }
        Period period = periods.findAll(sheet.id()).stream()
                .filter((p) -> p.contains(claim.getDueBy())).findFirst().orElse(null);
        if (period == null) return "X-" + claims.nextNumberIn(sheet.id(), "");
        return period.name() + "-" + claims.nextNumberIn(sheet.id(), period.name());
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.util.List;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Shares the claim with another person on the sheet. A SETTLED, VOID or DELETED claim is refused; so
 * is sharing it with its own person, with a person already holding a share, or past 100.00 in all.
 * A refusal writes nothing.
 */
public class ShareClaim {
    public void apply(@Val Sheet sheet, @Val Claim claim, @Val Sharing sharing, PersonRepository people,
            ClaimRepository claims, Out<Person> holderOut) throws InvalidClaimStatusException, InvalidClaimException {
        ClaimStatus status = claim.getStatus();
        if (status == ClaimStatus.SETTLED || status == ClaimStatus.VOID || status == ClaimStatus.DELETED) {
            throw new InvalidClaimStatusException("A " + status + " claim cannot be shared");
        }
        Person holder = people.find(sheet.id(), sharing.personId());
        if (holder == null) throw new InvalidClaimException("No such person to share the claim with");
        if (holder.getId() == claim.getPersonId()) {
            throw new InvalidClaimException("A claim cannot be shared with its own person");
        }
        List<ClaimShare> held = claims.sharesOf(claim);
        if (held.stream().anyMatch((s) -> s.personId() == holder.getId())) {
            throw new InvalidClaimException(holder.getName() + " already holds a share of the claim");
        }
        if (ClaimShare.total(held).add(sharing.share()).compareTo(new BigDecimal("100.00")) > 0) {
            throw new InvalidClaimException("A claim's shares cannot total more than 100.00");
        }
        claims.addShare(claim, new ClaimShare(holder.getId(), sharing.share()));
        holderOut.set(holder);
    }
}

